fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert_eq!(
        arr1.len(),
        arr2.len(),
        "Input arrays must have the same length"
    );

    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a / b)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_element_wise_divide_basic() {
        let a = vec![10, 20, 30];
        let b = vec![2, 4, 5];
        let result = element_wise_divide(&a, &b);
        assert_eq!(result, vec![5, 5, 6]);
    }

    #[test]
    fn test_element_wise_divide_edge_cases() {
        // Dividing by 1
        let a = vec![0, u32::MAX];
        let b = vec![1, 1];
        let result = element_wise_divide(&a, &b);
        assert_eq!(result, vec![0, u32::MAX]);

        // Larger numbers that still fit within i32::MAX
        let a = vec![2_000_000_000, 2_000_000_001];
        let b = vec![1, 2];
        let result = element_wise_divide(&a, &b);
        assert_eq!(result, vec![2_000_000_000, 1_000_000_000]);
    }
}